<div class="admin-pagehead"><div><span class="micro-label">PUBLICACIONES Y SEGUIMIENTO</span><h1>Historias de rescate</h1><p>Relatos individuales y avances que acompañan a los animales.</p></div><a href="/admin/historias/nueva" class="btn btn-primary">+ Nueva historia</a></div><section class="admin-panel"><div class="panel-head"><h2>Historias registradas</h2><label class="mini-search">⌕ <input data-filter-table type="search" placeholder="Buscar historias..."></label></div><div class="table-scroll"><table class="data-table" data-table><thead><tr><th>Título</th><th>Animal</th><th>Fecha</th><th>Estado</th><th>Publicación</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?= e($r['titulo']) ?></strong></td><td><?= e($r['animal']) ?></td><td><?= e($r['fecha_evento']) ?></td><td><?= e(str_replace('_',' ',$r['estado_proceso'])) ?></td><td><span class="chip <?= (int)$r['publicada']===1?'chip-soft':'chip-neutral' ?>"><?= (int)$r['publicada']===1?'Publicada':'Borrador' ?></span></td><td><a class="table-link" href="/admin/historias/<?= (int)$r['id'] ?>/editar">Editar ↗</a></td></tr><?php endforeach ?></tbody></table></div></section>
